'use strict';
// Platform-only console. No privileged credentials or customer content in this bundle.
const ccSections={inicio:'Inicio',negocios:'Negocios',usuarios:'Usuarios y accesos',comercial:'Comercial y finanzas',correos:'Correos y automatizaciones',sistema:'Sistema y diagnósticos',soporte:'Soporte e incidencias',datos:'Datos y almacenamiento',auditoria:'Seguridad y auditoría',configuracion:'Configuración'};
const ccSectionIcons={inicio:'grid',negocios:'shop',usuarios:'users',comercial:'wallet',correos:'mail',sistema:'chart',soporte:'help',datos:'download',auditoria:'shield',configuracion:'settings'};
const ccStates={queued:'En cola',processing:'En proceso',provider_accepted:'Aceptado por el proveedor',delivered:'Entrega confirmada',bounced:'Rebotado',failed:'Fallido',retry:'Reintento pendiente',quota_exhausted:'Cuota agotada',delivery_unknown:'Resultado desconocido',skipped:'Omitido',confirmed:'Confirmación de reserva',reminder:'Recordatorio',business_alert:'Aviso al negocio',invitation:'Invitación',security:'Seguridad',auth:'Autenticación',service:'Servicio',access:'Acceso',booking:'Reserva',mail:'Correo',subscription:'Suscripción',active:'Habilitado',pending:'Por habilitar',scheduled:'Programado',expired:'Vencido',suspended:'Suspendido',cancelled:'Cancelado',open:'Abierta',investigating:'En investigación',resolved:'Resuelta',unverified:'Sin comprobar',verified:'Comprobado por operador',waived:'Cortesía',pending_contact:'Por contactar',pending_payment:'Esperando pago',pending_verification:'Por verificar',low:'Baja',normal:'Normal',high:'Alta',critical:'Crítica',none:'Sin pausa administrativa',public:'Reservas públicas pausadas',all:'Todas las nuevas reservas pausadas',unknown:'Sin comprobar',operational:'Consulta confirmada'};
const ccRefreshIcon=()=>'<svg class="i cc-refresh-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 3v5h-5"/><path d="M21 12a9 9 0 1 1-9-9 9.75 9.75 0 0 1 6.74 2.74L21 8"/></svg>';
let ccSequence=0,ccData=null,ccParams={},ccSection='inicio',ccEntity=null;
const ccLabel=v=>ccStates[v]||v||'—';
const ccPlan=v=>({trial:'Prueba',individual:'ATRY Individual',negocio:'ATRY Negocio',pro:'ATRY Pro'})[v]||'Plan sin identificar';
const ccLicenseAction=v=>({activate:'Activación',renew:'Renovación',trial:'Prueba',suspend:'Suspensión',restore:'Restablecimiento',cancel:'Cancelación'})[v]||'Cambio de suscripción';
const ccLink=(section,query={})=>'#/admin/'+section+(Object.keys(query).length?'?'+new URLSearchParams(query):'');
const ccRead=(section,params={})=>api('/api/admin/control/'+section+'?'+new URLSearchParams(params),{fresh:true});
const ccDate=v=>{if(!v)return 'Sin dato verificable';const date=new Date(v);if(Number.isNaN(date.getTime()))return 'Fecha no disponible';return esc(new Intl.DateTimeFormat('es-UY',{timeZone:'America/Montevideo',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(date));};
const ccDay=v=>{if(!v)return 'Sin vencimiento registrado';const date=new Date(v);if(Number.isNaN(date.getTime()))return 'Fecha no disponible';const midnight=new Intl.DateTimeFormat('en-GB',{timeZone:'America/Montevideo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(date)==='00:00';return esc(new Intl.DateTimeFormat('es-UY',{timeZone:'America/Montevideo',day:'2-digit',month:'2-digit',year:'numeric'}).format(midnight?new Date(date.getTime()-1):date));};
const ccSize=n=>n==null?'Sin medición':new Intl.NumberFormat('es-UY',{maximumFractionDigits:1}).format(Number(n)/1048576)+' MiB';
const ccActionLabel=a=>({ 'subscription.activate':'Suscripción activada','subscription.renew':'Suscripción renovada','subscription.suspend':'Acceso suspendido','subscription.restore':'Acceso restablecido','subscription.cancel':'Suscripción cancelada','business.appearance.updated':'Apariencia actualizada','incident.insert':'Incidencia registrada',incident_create:'Incidencia registrada',request_state:'Estado comercial actualizado',retention_policy:'Política de conservación actualizada',settings:'Configuración comercial actualizada',incident:'Incidencia gestionada',reservations:'Nuevas reservas configuradas',business_mail:'Correo del negocio configurado',global_mail:'Correo operativo de plataforma configurado',block_user:'Acceso de cuenta modificado',revoke_sessions:'Sesiones revocadas',remove_membership:'Membresía retirada',mail_cancel:'Mensaje pendiente cancelado',mail_retry:'Reintento autorizado',followup:'Seguimiento actualizado',verify_payment:'Cobro comprobado manualmente',deletion_request:'Solicitud de baja registrada',mail_archive:'Contenido antiguo de correo limpiado'})[a]||'Operación administrativa';
const ccAuditResult=v=>({confirmed:'Confirmado',replayed:'Repetición segura',rejected:'Rechazado'})[v]||'Resultado registrado';
const ccMailError=code=>{if(!code)return 'Sin error registrado';const label=({BREVO_QUOTA:'Cuota del proveedor agotada',BREVO_HTTP_429:'Demasiadas solicitudes al proveedor',BREVO_HTTP_400:'El proveedor rechazó el mensaje',BREVO_HTTP_401:'Credencial del proveedor rechazada',BREVO_HTTP_403:'Envío no autorizado por el proveedor',ADMIN_CANCELLED:'Cancelado por administración'})[code]||'Revisar causa técnica';return `${esc(label)}<details class="cc-tech"><summary>Detalle técnico</summary><code>${esc(code)}</code></details>`;};
const ccTone=v=>['failed','bounced','critical','suspended'].includes(v)?'danger':['active','delivered','resolved','verified','operational'].includes(v)?'success':['pending','pending_contact','pending_payment','pending_verification','queued','retry','high','open','quota_exhausted','delivery_unknown'].includes(v)?'warning':['expired','public','all'].includes(v)?'orange':['processing','investigating','scheduled','provider_accepted'].includes(v)?'info':'neutral';
const ccBadge=v=>`<span class="cc-badge ${ccTone(v)}"><span class="cc-status-dot" aria-hidden="true"></span>${esc(ccLabel(v))}</span>`;
function ccTable(headers,rows){if(!rows.length)return '<div class="cc-empty">No hay registros para estos filtros.</div>';return `<div class="cc-table-wrap"><table class="cc-table"><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map((cell,index)=>`<td data-label="${esc(headers[index])}">${cell}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">No hay registros para estos filtros. Esto no certifica la salud del servicio.</td></tr>`}</tbody></table></div>`;}
const ccJSON=v=>`<details><summary>Ver detalle</summary><pre class="cc-json">${esc(JSON.stringify(v,null,2))}</pre></details>`;
const ccButton=(action,id,label,extra='')=>`<button class="btn secondary sm" data-cc-action="${action}" data-id="${esc(id)}" ${extra}>${esc(label)}</button>`;
function ccFilters(fields='q,status,plan,sort'){
 const parts={q:`<label>Buscar<input name="q" value="${esc(ccParams.q||'')}" maxlength="100" placeholder="Nombre, ID, contacto o solicitud"></label>`,status:`<label>Estado<select name="status">${option('','Todos')}${['pending','active','scheduled','expired','suspended','cancelled'].map(v=>option(v,ccLabel(v),ccParams.status===v)).join('')}</select></label>`,plan:`<label>Plan<select name="plan">${option('','Todos')}${['individual','negocio','pro','trial'].map(v=>option(v,ccPlan(v),ccParams.plan===v)).join('')}</select></label>`,sort:`<label>Orden<select name="sort">${[['created','Alta reciente'],['name','Nombre'],['deadline','Vencimiento']].map(([v,l])=>option(v,l,ccParams.sort===v)).join('')}</select></label>`,days:`<label>Vence en<select name="days">${option('','Cualquier fecha')}${[7,15,30].map(v=>option(v,v+' días',ccParams.days===String(v))).join('')}</select></label>`,state:`<label>Estado<select name="state">${option('','Todos',!ccParams.state)}${(ccSection==='correos'?['queued','processing','provider_accepted','delivered','failed','delivery_unknown','retry','quota_exhausted','skipped']:ccSection==='comercial'?['pending_contact','pending_payment','pending_verification','active','cancelled']:['open','investigating','resolved']).map(v=>option(v,ccLabel(v),ccParams.state===v)).join('')}</select></label>`,from:`<label>Desde<input type="date" name="from" value="${esc(ccParams.from||'')}"></label>`,until:`<label>Hasta<input type="date" name="until" value="${esc(ccParams.until||'')}"></label>`,actor:`<label>ID de administrador<input name="actor" value="${esc(ccParams.actor||'')}"></label>`};
 const active=fields.split(',').some(f=>ccParams[f]);
 return `<form data-cc-form="filters" class="cc-filters" ${fields==='state'?'data-cc-auto-filter':''}>${fields.split(',').map(f=>parts[f]).join('')}${fields==='state'?'':`<button class="btn">Aplicar</button>${active?`<a class="btn secondary" href="${ccLink(ccSection,{clear:1})}">Limpiar</a>`:''}`}</form>`;
}
function ccPager(d){if(!d||!d.total)return ''; const previous=Math.max(0,d.offset-d.limit),next=d.offset+d.limit;return `<div class="cc-pagination"><span>${d.total} registros · página ${Math.floor(d.offset/d.limit)+1}</span><a class="btn secondary sm" ${d.offset===0?'aria-disabled="true" tabindex="-1"':`href="${ccLink(ccSection,{...ccParams,offset:previous})}"`}>Anterior</a><a class="btn secondary sm" ${next>=d.total?'aria-disabled="true" tabindex="-1"':`href="${ccLink(ccSection,{...ccParams,offset:next})}"`}>Siguiente</a></div>`;}
function ccNavEntry(key,label){
 const active=key===ccSection;
 return `<a href="${ccLink(key)}" ${active?'aria-current="page"':''}>${ic(ccSectionIcons[key])}<span>${esc(label)}</span></a>`;
}
function ccShell(body,enter=false){
 const globalSearch=['negocios','usuarios','comercial','auditoria'].includes(ccSection)?'':`<form data-cc-form="global" role="search"><label class="sr-only" for="cc-global">Buscar en la plataforma</label><input id="cc-global" name="q" placeholder="Buscar negocio, persona o código" maxlength="100"><button class="btn secondary">Buscar</button></form>`;
 return `<div class="cc-shell cc-section-${ccSection}${enter?' cc-shell--enter':''}" data-cc-section="${ccSection}"><button class="sidebar-backdrop" data-action="close-menu" aria-label="Cerrar menú lateral" tabindex="-1"></button><aside class="cc-sidebar sidebar" id="sidebar" aria-label="Menú administrativo"><button class="btn secondary icon-only sidebar-close" data-action="close-menu" aria-label="Cerrar menú">${ic('x')}</button><div class="cc-brand">${brand()}<small>ADMINISTRACIÓN ATRY</small></div><nav aria-label="Administración de plataforma">${Object.entries(ccSections).map(([key,label])=>ccNavEntry(key,label)).join('')}</nav><a href="#/cuenta">${accountAvatar(state.me.user)}<span>Mi cuenta y seguridad</span></a><button class="btn secondary sm" data-action="logout">${ic('logout')}<span>Salir</span></button><div class="cc-mobile-account sidebar-bottom"><div class="user-card">${accountAvatar(state.me.user)}<a href="#/cuenta" class="grow truncate account-shortcut" aria-label="Mi cuenta y seguridad"><strong class="truncate">${esc(state.me.user.name)}</strong><span class="truncate">Mi cuenta y seguridad</span></a><button class="btn secondary icon-only sm" data-action="logout" aria-label="Cerrar sesión">${ic('logout')}</button></div></div></aside><main class="cc-main"><header class="cc-header"><button class="btn secondary icon-only cc-menu-toggle" data-action="toggle-menu" aria-label="Abrir menú" aria-controls="sidebar" aria-expanded="false">${ic('menu')}</button><div><span class="eyebrow">ATRY TURNOS · ADMINISTRACIÓN</span><h1>${esc(ccSections[ccSection])}</h1></div>${globalSearch}<button class="btn secondary sm" data-cc-refresh>${ccRefreshIcon()}<span>Actualizar</span></button><a class="btn secondary sm" href="#/cuenta">Mi cuenta</a><button class="btn secondary sm" data-action="logout">Salir</button></header><div id="cc-content" aria-live="polite">${body}</div><p class="cc-footnote">Solo administradores autorizados · sin acceso global al CRM privado.</p></main></div>${state.dialog?modalContent():''}`;
}
function ccMetric(label,value,section,query={},meta={}){return `<a class="cc-metric cc-tone-${Number(value)>0?meta.tone||'info':'neutral'}" href="${ccLink(section,query)}"><span class="cc-metric-label">${esc(label)}${ic(meta.icon||ccSectionIcons[section]||'chart')}</span><strong>${esc(value??'—')}</strong><span class="cc-metric-bottom">${esc(meta.hint||'Ver detalle')}${ic('arrow')}</span></a>`;}
function ccMetricStatic(label,value){return `<div class="cc-metric" role="group" aria-label="${esc(label)}"><span>${esc(label)}</span><strong>${esc(value??'—')}</strong></div>`;}
function ccOverview(d){
 const worker=d.worker,age=worker?.finished_at?Date.now()-Date.parse(worker.finished_at):Infinity,workerText=!worker?.finished_at?'Sin ejecución observada':worker.result==='error'?'Última ejecución con error':worker.result==='running'?'Ejecución iniciada, resultado pendiente':worker.result==='disabled'?'Envíos deshabilitados en este entorno':age>300000?'Sin finalización reciente':'Última ejecución completada';
 const workerTone=worker?.result==='error'?'danger':!worker?.finished_at||age>300000||worker.result==='running'?'warning':worker.result==='disabled'?'neutral':'success';
 const attention=d.attention||[];
 return `<section class="cc-hero"><div><span class="cc-hero-kicker">TU CENTRO DE OPERACIONES</span><h2>Todo a mano.<br> Lo importante, primero.</h2><p>Gestioná negocios, accesos y solicitudes desde un solo lugar.</p><span class="cc-checked">${ic('clock')} Datos consultados · ${ccDate(d.checked_at)}</span></div><div class="cc-hero-links"><a href="${ccLink('negocios',{status:'pending'})}">${ic('shop')}<span>Habilitar negocios<small>Revisar accesos pendientes</small></span>${ic('arrow')}</a><a href="${ccLink('comercial')}">${ic('wallet')}<span>Solicitudes y cobros<small>Gestionar el seguimiento comercial</small></span>${ic('arrow')}</a><a href="${ccLink('soporte')}">${ic('help')}<span>Soporte e incidencias<small>Dar seguimiento a cada caso</small></span>${ic('arrow')}</a></div></section>
 <div class="cc-section-heading"><h2>Resumen de la plataforma</h2><span>Seleccioná un indicador para ver el detalle</span></div><div class="cc-metrics">${ccMetric('Negocios habilitados',d.businesses?.active??0,'negocios',{status:'active'},{tone:'success',icon:'shop',hint:'Accesos habilitados'})}${ccMetric('Por habilitar',d.businesses?.pending??0,'negocios',{status:'pending'},{tone:'warning',icon:'lock',hint:'Revisar solicitudes'})}${ccMetric('Suspendidos',d.businesses?.suspended??0,'negocios',{status:'suspended'},{tone:'danger',icon:'block',hint:'Gestionar accesos'})}${ccMetric('Vencen en 7 días',d.expiring,'negocios',{days:7},{tone:'orange',icon:'calendar',hint:'Revisar renovaciones'})}${ccMetric('Solicitudes abiertas',d.requests,'comercial',{}, {tone:'info',icon:'wallet',hint:'Seguimiento comercial'})}${ccMetric('Incidencias abiertas',d.incidents,'soporte',{}, {tone:'warning',icon:'help',hint:'Revisar casos'})}${ccMetric('Correos fallidos',d.mail?.failed??0,'correos',{state:'failed'},{tone:'danger',icon:'mail',hint:'Investigar fallos'})}${ccMetric('Resultado desconocido',d.mail?.delivery_unknown??0,'correos',{state:'delivery_unknown'},{tone:'warning',icon:'info',hint:'Entrega sin confirmar'})}</div>
 <div class="cc-overview-bottom"><section class="cc-panel cc-attention"><div class="cc-panel-heading"><span class="cc-section-icon">${ic(attention.length?'bell':'checkcircle')}</span><div><h2>${attention.length?'Requieren tu atención':'Pendientes bajo control'}</h2><p class="muted small">${attention.length?'Errores y solicitudes, ordenados por prioridad y antigüedad.':'No hay pendientes detectados en las fuentes consultadas.'}</p></div><span class="cc-count">${attention.length}</span></div>${attention.length?ccTable(['Prioridad','Registro','Evidencia','Desde'],attention.map(a=>[ccBadge(a.priority<=1?'high':'normal'),`<a href="${ccLink(a.kind==='business'?'negocios/'+a.entity_id:a.kind==='mail'?'correos':'soporte',a.kind==='business'?{}:a.kind==='mail'?{state:a.code}:{})}">${esc(a.title)}</a>`,esc(a.code),ccDate(a.since)])):`<div class="cc-clear-state">${ic('checkcircle')}<strong>Sin acciones pendientes por ahora</strong><span>Este resumen no reemplaza las comprobaciones de servicio.</span></div>`}<p class="cc-source">Fuente: ${esc(d.source||'Sin fuente identificada')} · ${ccDate(d.checked_at)}</p></section>
 <section class="cc-panel cc-worker"><div class="cc-panel-heading"><span class="cc-section-icon">${ccRefreshIcon()}</span><div><h2>Automatizaciones</h2><p class="muted small">Última evidencia del proceso</p></div></div><span class="cc-badge ${workerTone}"><span class="cc-status-dot" aria-hidden="true"></span>${esc(workerText)}</span><p class="cc-worker-date">${ccDate(worker?.finished_at)}</p><p class="muted small">Una ejecución del proceso no confirma la entrega de cada correo ni la salud de Brevo.</p><a class="btn secondary" href="${ccLink('sistema')}">Ver diagnóstico ${ic('arrow')}</a></section></div>`;
}
function ccBusinessList(d){return ccFilters('q,status,plan,sort,days')+ccTable(['Negocio / contacto','Propietario','Plan','Estado','Último día incluido','Nuevas reservas'],d.rows.map(b=>[`<a href="${ccLink('negocios/'+b.id)}"><strong>${esc(b.name)}</strong></a><small>${esc(b.email||b.phone||b.slug)}</small>`,(b.owners||[]).map(o=>esc(o.name)).join(', ')||'Sin propietario registrado',esc(ccPlan(b.plan)),ccBadge(b.status),ccDay(b.deadline),ccBadge(b.reservation_scope)]))+ccPager(d);}
function ccBusiness(d){const b=d.data;state.adminBusinesses=[b];return `<a class="cc-back" href="${ccLink('negocios')}">← Negocios</a><section class="cc-panel"><h2>Resumen del negocio</h2><div class="cc-title-row"><div><h2>${esc(b.name)}</h2><div class="small muted">${esc(b.slug)} <details class="cc-tech"><summary>Identificador técnico</summary><code>${esc(b.id)}</code></details></div></div>${ccBadge(b.status)}</div><dl class="cc-facts"><div><dt>Contacto comercial</dt><dd>${esc(b.email)}<br>${esc(b.phone)}</dd></div><div><dt>Propietarios</dt><dd>${(b.owners||[]).map(o=>esc(o.name)+' · '+esc(o.email)).join('<br>')}</dd></div><div><dt>Plan / vencimiento</dt><dd>${esc(ccPlan(b.plan))} · ${ccDay(b.deadline)}</dd></div><div><dt>Profesionales / reservas</dt><dd>${b.active_staff.length} / ${b.staff_limit} profesionales · ${b.bookings} reservas</dd></div><div><dt>Correo del ciclo</dt><dd>${b.mail_usage?.accepted||0} aceptados · ${b.mail_usage?.reserved||0} reservados / ${b.mail_limit}<br>Reinicio: ${ccDate(b.mail_usage?.cycle_end)}</dd></div><div><dt>Capacidad restante</dt><dd>${Math.max(0,b.mail_limit-(b.mail_usage?.accepted||0)-(b.mail_usage?.reserved||0))} correos operativos</dd></div></dl><div class="cc-actions">${ccButton('subscription',b.id,'Gestionar suscripción')+ccButton('diagnostic',b.id,'Diagnóstico de reservas')}<a class="btn secondary sm" href="${ccLink('correos',{business_id:b.id})}">Ver correos</a><a class="btn secondary sm" href="${ccLink('soporte',{business_id:b.id})}">Ver soporte</a><a class="btn secondary sm" href="${ccLink('auditoria',{business_id:b.id})}">Ver historial</a></div><details class="cc-emergency"><summary>Acciones administrativas y de emergencia</summary><p>Estas acciones requieren una confirmación y quedan auditadas.</p><div class="cc-actions">${ccButton('incident_create',b.id,'Registrar incidencia')}${ccButton('reservations',b.id,'Pausar o restablecer reservas')}${ccButton('business_mail',b.id,b.mail_paused?'Reanudar correo operativo':'Pausar correo operativo')}${ccButton('deletion_request',b.id,'Solicitar baja o anonimización','data-type="business"')}</div></details><p class="small muted">Reservas: ${esc(ccLabel(b.reservation_scope))}. Las pausas conservan turnos existentes. El correo de seguridad se mantiene separado.</p></section><section class="cc-panel"><h2>Historial de suscripción</h2>${ccTable(['Fecha / operador','Acción','Importe declarado','Referencia','Comparación','Verificación'],(b.license_history||[]).map(e=>[ccDate(e.created_at)+'<small>'+esc(e.actor_name||'Atry')+'</small>',esc(ccLicenseAction(e.action)),money(e.amount_uyu),esc(e.reference||'Cortesía / sin referencia'),ccJSON({antes:e.before_state,despues:e.after_state,motivo:e.note}),e.verified_at?'Verificado por operador · '+ccDate(e.verified_at):e.amount_uyu>0?ccButton('verify_payment',e.id,'Registrar comprobación manual'):'Cortesía']))}<p class="muted small">Últimos 25 eventos. Una referencia no acredita conciliación bancaria. Los cobros comprobados se registran por separado.</p></section>`;}
function ccUsers(d){
 return ccFilters('q')+ccTable(['Cuenta','Confirmación / sesiones','Organizaciones','Gestionar'],d.rows.map(u=>{
  const memberships=(u.memberships||[]);
  const organizations=memberships.map(m=>`<div><a href="${ccLink('negocios/'+m.business_id)}">${esc(m.business_name)}</a> · ${esc(roleLabel(m.role))}</div>`).join('')||'Sin membresías';
  const removal=memberships.length?`<p>Retirar una membresía quita acceso solo a ese negocio; no elimina la cuenta ni sus otras organizaciones.</p>${memberships.map(m=>`<div class="cc-actions"><span>${esc(m.business_name)} · ${esc(roleLabel(m.role))}</span>${ccButton('remove_membership',u.id,'Retirar membresía','data-business="'+esc(m.business_id)+'"')}</div>`).join('')}`:'';
  const actions=`<details class="cc-account-actions"><summary>Abrir ficha y acciones</summary><p>Bloquear el acceso a Turnos no bloquea la identidad de Supabase. Revocar sesiones exige iniciar sesión nuevamente.</p><div class="cc-actions">${ccButton('block_user',u.id,u.blocked?'Desbloquear':'Bloquear','data-blocked="'+(u.blocked?'false':'true')+'"')}${ccButton('revoke_sessions',u.id,'Revocar sesiones')}${ccButton('deletion_request',u.id,'Solicitar baja','data-type="user"')}</div>${removal}<p><a href="${ccLink('auditoria',{q:u.id})}">Historial de esta cuenta</a> · <a href="#/recuperar" target="_blank" rel="noopener">Recuperación autoservicio</a></p></details>`;
  return [`<strong>${esc(u.name)}</strong><small>${esc(u.email)}</small>${ccBadge(u.blocked?'suspended':'active')}`,`${u.confirmed===null?'No disponible en entorno local':u.confirmed?'Correo confirmado':'Correo sin confirmar'}<small>Último acceso: ${ccDate(u.last_sign_in_at)}</small><small>${u.sessions} ${u.sessions===1?'sesión verificada':'sesiones verificadas'}</small>`,organizations,actions];
 }))+ccPager(d);
}
function ccMail(d){return `<div class="notice">Aceptación del proveedor no equivale a entrega. Un resultado desconocido exige evidencia externa antes de cualquier reenvío.</div><div class="cc-actions">${ccButton('global_mail','global','Pausar o reanudar correo operativo')}<a href="${ccLink('sistema')}">Worker, presupuesto y errores</a></div>`+ccFilters('state')+ccTable(['Negocio / tipo','Estado','Intentos / error','Proveedor','Próximo intento','Acción'],d.rows.map(j=>[`<a href="${ccLink('negocios/'+j.business_id)}">${esc(j.business_name||'Sistema')}</a><small>${esc(ccLabel(j.kind))}</small>`,esc(mailState(j.state)),`${j.attempts}<small>${ccMailError(j.last_error)}</small>`,j.provider_id?`<details class="cc-tech"><summary>Identificador del proveedor</summary><code>${esc(j.provider_id)}</code></details>`:'Sin aceptación registrada',['queued','retry','quota_exhausted'].includes(j.state)?ccDate(j.next_attempt_at):'No corresponde',`<div class="cc-actions">${['queued','retry','quota_exhausted'].includes(j.state)&&!['auth','security','password_reset','invitation'].includes(j.kind)?ccButton('mail_cancel',j.id,'Cancelar pendiente'):''}${j.state==='failed'&&!j.provider_id&&['BREVO_QUOTA','BREVO_HTTP_429','BREVO_HTTP_400','BREVO_HTTP_401','BREVO_HTTP_403'].includes(j.last_error)?ccButton('mail_retry',j.id,'Reintentar tras corregir causa'):''}${j.state==='delivery_unknown'?'<span class="small">Conciliar con Brevo por ID/fecha. Reenvío bloqueado.</span>':''}</div>`]))+ccPager(d);}
function ccRequests(d){
 state.adminCommercial={requests:d.rows};
 const rows=d.rows.map(r=>[`<strong>${esc(r.code)}</strong><small><a href="${ccLink('negocios/'+r.business_id)}">${esc(r.business_name)}</a> · ${ccDate(r.created_at)}</small>`,esc(ccPlan(r.plan))+'<small>'+money(r.price_uyu)+'</small>',ccBadge(r.state)+'<small>'+esc(ccLabel(r.payment_state))+'</small>',esc(r.note||'Sin nota')+'<small>Próximo contacto: '+esc(r.next_contact||'Sin fecha')+'</small>',`<div class="cc-actions"><a class="btn secondary sm" href="https://wa.me/${esc(String(r.phone).replace(/[^0-9]/g,''))}" target="_blank" rel="noopener noreferrer">Abrir WhatsApp</a>${ccButton('followup',r.id,'Seguimiento')+(['pending_contact','pending_payment','pending_verification'].includes(r.state)?ccButton('request_state',r.id,'Cambiar estado'):'')}${['pending_contact','pending_payment','pending_verification'].includes(r.state)?ccButton('approve',r.id,'Verificar y habilitar'):''}</div><small>Abrir enlace no confirma contacto.</small>`]);
 return `<section class="cc-panel"><h2>Solicitudes comerciales</h2><p>Registrá el contacto, comprobá el pago fuera de Atry y habilitá solo después de verificarlo.</p>${ccFilters('q,state')}${rows.length?ccTable(['Solicitud / negocio','Plan / propuesta','Estado','Seguimiento','Acciones'],rows):'<div class="cc-empty">No hay solicitudes con estos filtros. Las suscripciones habilitadas se consultan en Negocios.</div>'}${ccPager(d)}<a href="${ccLink('negocios',{status:'active'})}">Ver suscripciones habilitadas</a> · <a href="${ccLink('negocios',{days:7})}">Ver próximos vencimientos</a></section>`;
}
function ccIncidents(d){return '<div class="cc-actions">'+ccButton('incident_create','new','Registrar incidencia')+'</div>'+ccFilters('state')+(d.rows.length?ccTable(['Incidencia','Negocio','Prioridad / estado','Resolución','Acción'],d.rows.map(i=>[`<strong>${esc(i.subject)}</strong><details class="cc-tech"><summary>Identificador técnico</summary><code>${esc(i.id)}</code></details><small>${ccDate(i.created_at)} · ${esc(ccLabel(i.category))}</small>`,`<a href="${ccLink('negocios/'+i.business_id)}">${esc(i.business_name)}</a>${i.priority_support?'<small>Atención Pro · sin SLA garantizado</small>':''}`,ccBadge(i.priority)+' '+ccBadge(i.state),esc(i.resolution||'Sin resolución documentada'),ccButton('incident',i.id,'Gestionar incidencia')])):'<div class="cc-empty">No hay incidencias con este filtro. Podés registrar un reporte recibido por WhatsApp u otro canal.</div>')+ccPager(d);}
function ccAudit(d){return ccFilters('q,actor,from,until')+`<button class="btn secondary sm" data-cc-export>Exportar esta página CSV</button>`+ccTable(['Fecha / operación','Administrador','Acción / entidad','Motivo / resultado','Antes / después'],d.rows.map(e=>[ccDate(e.created_at),esc(e.actor_name||e.actor_id),esc(ccActionLabel(e.action))+'<details class="cc-tech"><summary>Identificador técnico</summary><code>'+esc(e.entity_id)+'</code></details>',esc(e.reason)+'<small>'+esc(ccAuditResult(e.result))+'</small>',ccJSON({accion:e.action,resultado:e.result,antes:e.before_state,despues:e.after_state})]))+ccPager(d);}
function ccSystem(d){return `<section class="cc-panel"><h2>Estado basado en evidencia</h2><p>Comprobado ${ccDate(d.checked_at)} · ${esc(d.evidence)}</p>${ccTable(['Componente','Estado'],[['PostgreSQL / API administrativa',ccBadge(d.database)],...['auth','public_booking','edge','realtime','brevo'].map(k=>[({auth:'Acceso y autenticación',public_booking:'Reservas públicas',edge:'Funciones de servidor',realtime:'Actualizaciones en vivo',brevo:'Proveedor de correo'})[k],ccBadge(d[k])])])}<p class="muted">Sin comprobar significa que no hay un chequeo independiente reciente disponible.</p></section><section class="cc-panel"><h2>Worker y presupuesto diario UTC</h2><dl class="cc-facts"><div><dt>Último inicio</dt><dd>${ccDate(d.worker?.started_at)}</dd></div><div><dt>Última finalización</dt><dd>${ccDate(d.worker?.finished_at)}</dd></div><div><dt>Resultado del proceso</dt><dd>${esc(({ok:'Completado',error:'Con error',running:'En curso'})[d.worker?.result]||'Sin ejecución comprobada')}</dd></div><div><dt>Intentos de correo hoy</dt><dd>${d.budget?esc(d.budget.attempts)+' / '+esc(d.budget.limit_count):'Sin registro diario'}</dd></div></dl>${d.mail_schedule?'<p>Programación de correo: '+(d.mail_schedule.some(s=>s.active)?'activa cada dos minutos según cron del proyecto':'sin programación activa')+'.</p>':''}<p>El heartbeat mide ejecución del worker. No confirma recepción en el buzón.</p></section><section class="cc-panel"><h2>Errores recientes</h2>${ccTable(['Código','Cantidad','Última observación'],(d.errors||[]).map(e=>[esc(e.code),e.count,ccDate(e.latest)]))}</section><section class="cc-panel"><h2>Respuesta ante caída total</h2><ol><li>Comprobar la página pública y el estado del proveedor desde fuera de la aplicación.</li><li>Consultar GitHub Actions y Supabase, exclusivamente el proyecto de ATRY Turnos.</li><li>No repetir envíos desconocidos ni alterar datos para probar una caída.</li><li>Registrar incidente y evidencia; recuperar mediante procedimiento documentado y entorno aislado.</li></ol></section>`;}
function ccGuides(){const guides=[
 ['Una persona no puede entrar','Usuarios y accesos','Buscá su correo. Comprobá verificación, bloqueo, sesiones y membresías. Si olvidó la contraseña, usá el procedimiento autoservicio; revocar sesiones obliga a volver a ingresar.','usuarios'],
 ['Un negocio no puede operar','Negocios','Abrí la ficha y revisá vigencia, suspensión, propietarios y pausa de nuevas reservas. El diagnóstico de reservas comprueba servicios, profesionales y horarios.','negocios'],
 ['Un cliente no puede reservar','Negocios','Abrí el negocio y ejecutá Diagnóstico de reservas. Si esas reglas pasan, comprobá la fecha solicitada, ausencias y ocupación de esa hora con el propietario.','negocios'],
 ['Un correo no se envió','Correos','Revisá estado, motivo de fallo, cuota y última ejecución. Un resultado desconocido requiere evidencia del proveedor antes de reenviar.','correos'],
 ['Una suscripción no se activó','Comercial','Buscá la solicitud, comprobá el pago fuera de Atry y abrí Gestionar suscripción. Revisá comienzo, último día de servicio y plan antes de confirmar.','comercial'],
 ['El proceso automático dejó de ejecutarse','Sistema','Revisá última finalización, cron y errores. Si no hay ejecución reciente, consultá la función atry-mail en el proyecto Supabase de Turnos y registrá una incidencia.','sistema']
 ];return `<section class="cc-panel"><h2>Resolver problemas frecuentes</h2><p class="small muted">Estos recorridos usan los datos comprobados en cada sección. No ejecutan reparaciones por sí solos.</p><div class="cc-guides">${guides.map(([title,section,steps,route])=>`<details><summary>${esc(title)}</summary><p>${esc(steps)}</p><a href="${ccLink(route)}">Abrir ${esc(section)}</a></details>`).join('')}</div></section>`;}
function ccStorage(d){return `<section class="cc-panel"><h2>Datos y almacenamiento</h2><p>Comprobado ${ccDate(d.checked_at)}</p><dl class="cc-facts"><div><dt>PostgreSQL · tamaño de base medido</dt><dd>${d.postgres_database_bytes==null?'No disponible':ccSize(d.postgres_database_bytes)}</dd></div><div><dt>Supabase Storage</dt><dd>${d.storage?esc(d.storage.objects)+' archivos · '+(d.storage_bytes==null?'Tamaño incompleto':ccSize(d.storage_bytes)+' registrados'):'Sin medición verificada'}</dd></div></dl>${ccTable(['Categoría','Registros medidos'],Object.entries(d.logical_rows||{}).map(([k,v])=>[esc(({businesses:'Negocios',users:'Usuarios',customers:'Clientes',bookings:'Reservas',mail_jobs:'Trabajos de correo'})[k]||k),new Intl.NumberFormat('es-UY').format(v)]))}<p>Eliminar filas no libera inmediatamente espacio físico en PostgreSQL.</p></section><section class="cc-panel"><h2>Retención y eliminación</h2><p>Podés iniciar una solicitud y revisar dependencias desde la ficha de negocio o usuario. La eliminación definitiva de negocios y la limpieza automática están deshabilitadas hasta definir retención y validar Auth, base de datos y archivos en un entorno aislado.</p></section><section class="cc-panel"><h2>Respaldos y recuperación</h2><p>Último respaldo verificable: ${ccDate(d.backup?.last_verified)}. Estado: ${esc(ccLabel(d.backup?.status))}.</p><p>No hay restauración de producción desde esta consola. Un archivo previo no demuestra cobertura de Auth, Storage, secretos o recuperación ensayada.</p></section>`;}
async function ccRenderSection(requestToken){
 const map={negocios:ccEntity?'business':'businesses',usuarios:'users',comercial:'requests',correos:'mail',soporte:'incidents',auditoria:'audit',sistema:'system',datos:'storage',inicio:'overview',configuracion:'settings'},key=map[ccSection];
 const d=await ccRead(key,{...ccParams,...(ccEntity?{business_id:ccEntity}:{})});if(requestToken!==ccSequence)return '';ccData=d;
 if(ccSection==='configuracion'){
  state.adminPlans=d.plans;return `<section class="cc-panel"><h2>Planes y capacidades</h2><p>Los cambios afectan a todos los negocios del plan. Se verifica la revisión antes de guardar.</p>${ccTable(['Plan','Precio / mes','Profesionales','Correos / ciclo','Capacidades independientes','Acción'],d.plans.map(p=>[esc(p.name),money(p.price_uyu),p.staff_limit,p.mail_limit,['statistics','advanced','exports'].map(k=>esc(commercialLabels[k])+': '+(p.features[k]?'Sí':'No')).join('<br>'),`<button class="btn secondary sm" data-action="edit-plan" data-code="${p.code}">Ajustar plan</button>`]))}</section><section class="cc-panel"><h2>Capacidad comercial</h2><dl class="cc-facts"><div><dt>Capacidad mensual disponible</dt><dd>${esc(d.capacity?.monthly_available??'Sin dato')} correos</dd></div><div><dt>Cuotas mensuales comprometidas</dt><dd>${esc(d.capacity?.monthly_committed??'Sin dato')} correos</dd></div></dl><p>Capacidad comprometida no es consumo ni saldo de Brevo. Cambiar límites aquí no contrata servicios.</p><form data-commercial-form="settings" class="cc-filters">${field('whatsapp','WhatsApp central',d.settings.whatsapp,'text','required') }<label>Impuestos<select name="tax_status">${[['pending','Pendiente de definir'],['included','Impuestos incluidos'],['excluded','Impuestos no incluidos']].map(([v,label])=>option(v,label,d.settings.tax_status===v)).join('')}</select></label>${field('provider_daily_limit','Capacidad diaria verificada',d.settings.provider_daily_limit,'number','min="1" max="100000" required')}${field('security_reserve','Reserva de seguridad',d.settings.security_reserve,'number','min="0" max="99999" required')}<input type="hidden" name="expected_revision" value="${d.settings.revision}"><label>Motivo del cambio<input name="reason" required minlength="5" maxlength="500"></label><button class="btn">Revisar y guardar</button></form></section>`;
 }
 const render={inicio:ccOverview,negocios:ccEntity?ccBusiness:ccBusinessList,usuarios:ccUsers,correos:ccMail,comercial:ccRequests,soporte:ccIncidents,auditoria:ccAudit,sistema:ccSystem,datos:ccStorage};let body=render[ccSection](d);if(ccSection==='sistema')body+=ccGuides();
 if(ccSection==='datos'){try{const r=await ccRead('retention');body+='<section class="cc-panel"><h2>Limpieza manual de correos terminales</h2>'+`<dl class="cc-facts"><div><dt>Conservación definida</dt><dd>${r.policy_days?esc(r.policy_days)+' días':'Sin definir; limpieza bloqueada'}</dd></div><div><dt>Correos elegibles</dt><dd>${esc(r.eligible)}</dd></div><div><dt>Contenido estimado</dt><dd>${ccSize(r.estimated_payload_bytes)}</dd></div></dl>`+'<div class="cc-actions">'+ccButton('retention_policy','global','Definir política')+(r.policy_days&&r.eligible?ccButton('mail_archive','global','Revisar y limpiar contenido'):'')+'</div><p>Sin política definida no se elimina contenido. La limpieza preserva registros, cuotas y deduplicación.</p></section>';}catch(e){body+='<p role="alert">Retención: '+esc(e.message)+'</p>';}}
 if(ccSection==='comercial'){
  const results=await Promise.allSettled([ccRead('finance',ccParams)]);if(results[0].status==='fulfilled'){const f=results[0].value;body=`<section class="cc-panel"><h2>Finanzas · registro manual</h2>${ccFilters('from,until')}<div class="cc-metrics">${ccMetricStatic('Importes declarados',money(f.declared_uyu))}${ccMetricStatic('Comprobados por operador',money(f.operator_verified_uyu))}${ccMetricStatic('Cortesías',f.courtesies)}${ccMetricStatic('Valor mensual estimado',money(f.monthly_estimate_uyu))}</div><p>Sin conciliación bancaria automática ni facturación fiscal. Vencimiento no implica deuda; no hay saldo de deuda verificado.</p></section>`+body;}else body='<div class="notice">Finanzas no disponible: '+esc(results[0].reason.message)+'</div>'+body;
 }if(ccSection==='negocios'&&!ccEntity&&ccParams.global==='1'){try{const u=await ccRead('users',{q:ccParams.q||'',limit:10});body+='<section class="cc-panel"><h2>Usuarios coincidentes</h2>'+ccTable(['Cuenta','Correo','Acceso'],u.rows.map(x=>[esc(x.name),esc(x.email),`<a href="${ccLink('usuarios',{q:x.email})}">Abrir cuenta</a>`]))+'</section>';}catch(e){body+='<p role="alert">Usuarios: '+esc(e.message)+'</p>';}}return body;
}
async function adminView(options={}){
 if(!ensureAuth())return;if(!state.me.user.platform_admin){nav('/app');return;}
 const url=new URL(location.hash.slice(1),'https://atry.internal'),parts=url.pathname.split('/');ccSection=parts[2]||'inicio';if(!ccSections[ccSection])ccSection='inicio';ccEntity=ccSection==='negocios'&&parts[3]?parts[3]:null;
 ccParams=Object.fromEntries(url.searchParams);if(ccParams.clear){sessionStorage.removeItem('atry-cc:'+state.me.user.id+':'+ccSection);ccParams={};}if(!url.search&&ccSection!=='inicio'&&!ccEntity){try{ccParams=JSON.parse(sessionStorage.getItem('atry-cc:'+state.me.user.id+':'+ccSection)||'{}');}catch{ccParams={};}}
 document.title=ccSections[ccSection]+' · ATRY Control Center';const token=++ccSequence;
 const previousSection=root.querySelector('.cc-shell')?.dataset.ccSection;
 const changing=previousSection&&previousSection!==ccSection;
 if(changing)root.querySelector('.cc-shell')?.classList.add('cc-shell--loading');
 else if(!options.refresh||!previousSection)page(ccShell('<div class="cc-panel" role="status">Cargando '+esc(ccSections[ccSection])+'…</div>'));
 const show=async body=>{
  root.querySelector('.cc-shell')?.classList.remove('cc-shell--loading');
  const render=()=>page(ccShell(body,changing));
  if(changing&&innerWidth>760&&document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
   await document.startViewTransition(render).finished.catch(()=>{});
  }else render();
 };
 try{const body=await ccRenderSection(token);if(token!==ccSequence)return;await show(body+`<p class="cc-source">Fuente de sección · ${ccDate(ccData.checked_at)}</p>`);}catch(e){if(token!==ccSequence)return;if(e.status===401){state.me=null;nav('/login');return;}await show(`<section class="cc-panel" role="alert"><h2>No pudimos cargar ${esc(ccSections[ccSection])}</h2><p>${esc(e.message)}</p><button class="btn" data-cc-refresh>Reintentar esta sección</button><a href="#/admin/inicio">Volver al inicio</a></section>`);}
}
